  S.push(`<g transform="${T}">`+pth(H,"url(#gh)",'stroke-width=".7"')+tone("M4 0 L7 0 L7 16 L4.6 14 Z","#c9a040",.6)+cl("M7.6 17 L7.6 14 M10.4 16.2 L10.4 13.6 M5 12 C6 13 7 13 7.6 12",  "#a87a20",.4)+`</g>`);
