    if(mode==="run")u.hp=Math.max(1,Math.round(u.maxhp*Math.min(1,G.run.hp[u.id]??1)));
    else if(opt.hp&&opt.hp[u.id]!=null)u.hp=Math.max(1,Math.round(u.maxhp*Math.min(1,opt.hp[u.id])));
